const D = { density:.55, energy:.6, hue:335, speed:1, scale:1, x:.5, y:.5, wind:.2, tumble:.6, style:'sakura', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const sakura=st==='sakura',ink=st==='ink',riso=st==='riso',woodblock=st==='woodblock',wire=st==='wire';

const en=clp(P.energy,0,1);
// gust on bass, blended over baseline breeze
const breeze=Math.sin(K.t*0.35)*0.5+Math.sin(K.t*0.13+1.7)*0.5;
const gust=(A.bass*0.9+A.lowmid*0.4);
const windX=(P.wind-0.2)*2 + breeze*(0.35+en*0.5) + gust*0.8;

const nP=Math.round(lrp(16,120,clp(P.density,0,1)));
const fall=(0.05+en*0.09)*P.speed;
const tmb=0.5+P.tumble*2.4;

function petalCol(seedv,lifeY){
  if(ink){ return [md(H,360), 6, lrp(30,58,frc(seedv))]; }
  if(riso){ return frc(seedv*3.3)<0.5? [md(H,360),72,92] : [md(H+150,360),58,80]; }
  if(woodblock){ return [md(H+lrp(-8,10,frc(seedv)),360), lrp(30,62,frc(seedv*1.7)), lrp(78,95,frc(seedv))]; }
  // sakura: soft pinks, pale to warm
  return [md(H+lrp(-14,16,frc(seedv)),360), lrp(18,44,frc(seedv*1.9)), lrp(88,100,frc(seedv))];
}

function petalShape(rr,fillOn){
  // single blossom petal with notch, pointing up (-y)
  if(fillOn) beginShape();
  else beginShape();
  vertex(0, rr*0.9);
  bezierVertex(rr*0.62,rr*0.5, rr*0.62,-rr*0.55, rr*0.12,-rr*0.92);
  bezierVertex(rr*0.05,-rr*0.78, -rr*0.05,-rr*0.78, -rr*0.12,-rr*0.92);
  bezierVertex(-rr*0.62,-rr*0.55, -rr*0.62,rr*0.5, 0,rr*0.9);
  endShape(CLOSE);
}

for(let i=0;i<nP;i++){
  const sd=i+1;
  const sz=u*(0.016+0.03*fr(sd*2))*P.scale*(0.7+en*0.5);
  const spd=0.6+fr(sd*3)*0.9;
  const life=frc(fr(sd*5) + K.t*fall*spd);          // 0 top -> 1 bottom, continuous
  const sway=Math.sin(K.t*1.2*tmb*spd + fr(sd*7)*6.28)*u*0.07*(0.5+P.tumble);
  const px=frc(fr(sd*11) + windX*life*0.35 + K.t*0.006*windX) * (W+u*0.2) - u*0.1 + sway;
  const py=life*(Hh+u*0.1)-u*0.05;
  const rot=(fr(sd*13)*6.28) + K.t*tmb*spd*(fr(sd*17)<0.5?1:-1) + gust*2;
  const flip=0.35+0.65*Math.abs(Math.sin(K.t*1.6*tmb*spd + fr(sd*19)*6.28)); // foreshorten = tumble in 3D
  const col=petalCol(fr(sd*23), life);

  push();
  translate(px,py);
  rotate(rot);
  scale(1, flip);

  if(wire){
    noFill(); stroke(col[0],clp(col[1]+20,0,100),col[2], 85); strokeWeight(Math.max(0.8,u*0.0016));
    petalShape(sz,false);
    line(0,sz*0.85,0,-sz*0.85);
  } else if(woodblock){
    fill(col[0],col[1],col[2]); stroke(md(H+2,360),70,28,90); strokeWeight(Math.max(1,u*0.0022));
    petalShape(sz,true);
    noStroke();
  } else if(ink){
    noStroke();
    // dry-brush: two offset tonal strokes
    fill(col[0],col[1],col[2], 78); petalShape(sz,true);
    fill(col[0],col[1],clp(col[2]-18,0,100), 55); push(); translate(sz*0.06,-sz*0.05); scale(0.7,0.86); petalShape(sz,true); pop();
  } else if(riso){
    noStroke();
    // misregistration: second ink offset + halftone feel via alpha
    const c2=frc(fr(sd*23)*3.3)<0.5? [md(H+150,360),58,80] : [md(H,360),72,92];
    fill(c2[0],c2[1],c2[2], 62); push(); translate(sz*0.14,sz*0.1); petalShape(sz,true); pop();
    fill(col[0],col[1],col[2], 78); petalShape(sz,true);
  } else {
    // sakura: soft gradient body + subtle vein, no hard outline
    noStroke();
    fill(col[0],clp(col[1]-8,0,100),col[2], 92); petalShape(sz,true);
    fill(md(H+8,360),clp(col[1]+22,0,100),clp(col[2]-6,0,100), 55); push(); scale(0.6,0.94); petalShape(sz,true); pop();
    stroke(md(H+4,360),clp(col[1]+30,0,100),clp(col[2]-14,0,100),40); strokeWeight(Math.max(0.6,u*0.0012)); line(0,sz*0.6,0,-sz*0.55); noStroke();
  }
  pop();
}

blendMode(BLEND);
drawingContext.shadowBlur=0;
